#include <stdio.h>
#include <stdlib.h>

struct Node {
    int vertex;
    int weight;
    struct Node* next;
};

struct Node* graph[50];
int visited[50];
int nodecount;

// Create new node
struct Node* createNode(int vertex, int weight) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->vertex = vertex;
    newNode->weight = weight;
    newNode->next = NULL;
    return newNode;
}

// Add edge
void addEdge(int src, int dest, int weight) {
    struct Node* newNode = createNode(dest, weight);
    newNode->next = graph[src];
    graph[src] = newNode;
}

// Print graph
void printGraph() {
    printf("\nGraph adjacency list:\n");
    for (int i = 0; i < nodecount; i++) {
        printf("%d -> ", i);
        struct Node* temp = graph[i];
        while (temp != NULL) {
            printf("%d(%d) ", temp->vertex, temp->weight);
            temp = temp->next;
        }
        printf("\n");
    }
}

// DFS traversal
void DFS(int v) {
    visited[v] = 1;
    printf("%d ", v);

    struct Node* temp = graph[v];
    while (temp != NULL) {
        if (!visited[temp->vertex]) {
            DFS(temp->vertex);
        }
        temp = temp->next;
    }
}

// BFS traversal
void BFS(int start) {
    int queue[50];
    int front = 0, rear = 0;

    for (int i = 0; i < nodecount; i++)
        visited[i] = 0;

    visited[start] = 1;
    queue[rear++] = start;

    printf("\nBFS: ");
    while (front < rear) {
        int current = queue[front++];
        printf("%d ", current);
        struct Node* temp = graph[current];
        while (temp != NULL) {
            if (!visited[temp->vertex]) {
                visited[temp->vertex] = 1;
                queue[rear++] = temp->vertex;
            }
            temp = temp->next;
        }
    }
    printf("\n");
}

// Delete node (remove all edges connected to it)
void deleteNode(int vertex) {
    // Remove adjacency list of that vertex
    struct Node* temp = graph[vertex];
    while (temp != NULL) {
        struct Node* del = temp;
        temp = temp->next;
        free(del);
    }
    graph[vertex] = NULL;

    // Remove edges pointing to this vertex
    for (int i = 0; i < nodecount; i++) {
        if (i == vertex) continue;
        struct Node* curr = graph[i];
        struct Node* prev = NULL;
        while (curr != NULL) {
            if (curr->vertex == vertex) {
                if (prev == NULL)
                    graph[i] = curr->next;
                else
                    prev->next = curr->next;
                free(curr);
                break;
            }
            prev = curr;
            curr = curr->next;
        }
    }
    printf("\nDeleted node %d\n", vertex);
}

// Prim's Algorithm (MST)
void prims() {
    int selected[50] = {0};
    selected[0] = 1;
    int edges = 0;
    int total = 0;

    printf("\nEdges in MST:\n");
    while (edges < nodecount - 1) {
        int min = 9999;
        int from = -1, to = -1;

        for (int i = 0; i < nodecount; i++) {
            if (selected[i]) {
                struct Node* temp = graph[i];
                while (temp != NULL) {
                    if (!selected[temp->vertex] && temp->weight < min) {
                        min = temp->weight;
                        from = i;
                        to = temp->vertex;
                    }
                    temp = temp->next;
                }
            }
        }

        if (to == -1) break; // no more connections
        printf("%d -> %d  (weight %d)\n", from, to, min);
        total += min;
        selected[to] = 1;
        edges++;
    }

    printf("Total weight of MST = %d\n", total);
}

// Main
int main() {
    nodecount = 4;

    for (int i = 0; i < nodecount; i++)
        graph[i] = NULL;

    addEdge(0, 1, 4);
    addEdge(0, 2, 5);
    addEdge(1, 2, 2);
    addEdge(2, 1, 7);
    addEdge(2, 3, 1);

    printGraph();

    printf("\nDFS: ");
    for (int i = 0; i < nodecount; i++) visited[i] = 0;
    DFS(0);

    BFS(0);

    deleteNode(2);
    printGraph();

    prims();

    return 0;
}
