struct Node {
    int v;
    struct Node* next;
};

struct Node* g[50];
int vis[50];

void add(int u, int v) {
    struct Node* n = malloc(sizeof(struct Node));
    n->v = v;
    n->next = g[u];
    g[u] = n;
}

void dfs(int v) {
    printf("%d ", v);
    vis[v] = 1;
    for (struct Node* t = g[v]; t; t = t->next)
        if (!vis[t->v]) dfs(t->v);
}

void bfs(int s, int n) {
    int q[50], f = 0, r = 0;
    for (int i = 0; i < n; i++) vis[i] = 0;
    vis[s] = 1; q[r++] = s;
    while (f < r) {
        int x = q[f++];
        printf("%d ", x);
        for (struct Node* t = g[x]; t; t = t->next)
            if (!vis[t->v]) vis[t->v] = 1, q[r++] = t->v;
    }
}

int main() {
    add(0,1); add(0,2); add(1,2); add(2,0); add(2,3); add(3,3);
    printf("DFS: "); dfs(2);
    for (int i = 0; i < 50; i++) vis[i] = 0;
    printf("\nBFS: "); bfs(2, 4);
